package smartcampus;
import java.awt.*;import java.sql.*;
public class Reservation extends Panel{
 TextField plate=UI.field(""),slot=UI.field(""),start=UI.field("2026-09-02 10:00:00"),end=UI.field("2026-09-02 12:00:00"); TextArea out=new TextArea();
 Reservation(Frame f){setLayout(new BorderLayout(10,10));setBackground(UI.BG);add(UI.label("PARKING RESERVATION",22,UI.NAVY),BorderLayout.NORTH);Panel form=new Panel(new GridLayout(0,2,8,8));String[] n={"Vehicle Plate","Slot Code","Start (yyyy-mm-dd hh:mm:ss)","End (yyyy-mm-dd hh:mm:ss)"};TextField[] a={plate,slot,start,end};for(int i=0;i<n.length;i++){form.add(new Label(n[i]));form.add(a[i]);}Button b=UI.button("RESERVE SLOT",UI.GREEN);form.add(b);add(form,BorderLayout.WEST);out.setEditable(false);add(out,BorderLayout.CENTER);b.addActionListener(e->save());}
 void save(){try(Connection c=DB.get()){PreparedStatement q=c.prepareStatement("select vehicle_id from vehicles where plate_number=?");q.setString(1,plate.getText().trim());ResultSet vr=q.executeQuery();if(!vr.next()){out.setText("Vehicle not found.");return;}int vid=vr.getInt(1);q=c.prepareStatement("select slot_id from parking_slots where slot_code=? and status='Available'");q.setString(1,slot.getText().trim());ResultSet sr=q.executeQuery();if(!sr.next()){out.setText("Slot not available.");return;}int sid=sr.getInt(1);q=c.prepareStatement("select reservation_id from reservations where slot_id=? and status='Confirmed' and start_time < ? and end_time > ?");q.setInt(1,sid);q.setString(2,end.getText());q.setString(3,start.getText());if(q.executeQuery().next()){out.setText("Conflict: slot already reserved in this time range.");return;}q=c.prepareStatement("insert into reservations(vehicle_id,slot_id,start_time,end_time,status) values(?,?,?,?,'Confirmed')");q.setInt(1,vid);q.setInt(2,sid);q.setString(3,start.getText());q.setString(4,end.getText());q.executeUpdate();c.createStatement().executeUpdate("update parking_slots set status='Reserved' where slot_id="+sid);out.setText("Reservation confirmed for "+plate.getText()+" at "+slot.getText());}catch(Exception e){out.setText("Error: "+e.getMessage());}}
}
